
/* RIM UPDATE-5 — reliability, advertising controls, attachments and media performance.
   Additive patch: preserves the existing visual system and original application modules. */
(()=>{'use strict';
 const $=id=>document.getElementById(id);
 const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const notify=(s)=>{if(typeof toast==='function')toast(s);else console.info('[RIM]',s)};
 const admin=()=>!!(window.isImperator?.() || (typeof IMPERIAL_FEATURES!=='undefined'&&IMPERIAL_FEATURES.admin===true));
 const canManageAds=()=>admin();
 const extOf=n=>{const e=(String(n||'').split('.').pop()||'bin').toLowerCase();return /^[a-z0-9]{1,8}$/.test(e)?e:'bin'};
 const mediaKind=f=>f.type.startsWith('image/')?'image':f.type.startsWith('video/')?'video':f.type.startsWith('audio/')?'audio':(['application/pdf','text/plain','application/msword','application/vnd.openxmlformats-officedocument.wordprocessingml.document','application/vnd.ms-excel','application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'].includes(f.type)?'document':'file');

 // Shared, truthful loading treatment. It does not add artificial delays.
 const style=document.createElement('style');style.id='rim-update5-polish';style.textContent=`
 .rim-skeleton{position:relative;overflow:hidden;background:var(--panel2);border:1px solid var(--border);border-radius:12px;min-height:54px;margin:8px 0}
 .rim-skeleton:after{content:'';position:absolute;inset:0;transform:translateX(-100%);background:linear-gradient(90deg,transparent,rgba(255,255,255,.075),transparent);animation:rimShimmer 1.35s infinite}
 @keyframes rimShimmer{to{transform:translateX(100%)}}
 .rim-attachment{display:block;margin-top:8px;max-width:min(100%,440px);border:1px solid var(--border);border-radius:11px;overflow:hidden;background:var(--panel2)}
 .rim-attachment img,.rim-attachment video{display:block;max-width:100%;max-height:340px;width:auto;height:auto}
 .rim-attachment audio{display:block;width:100%;min-width:220px}
 .rim-attachment-file{display:flex;gap:10px;align-items:center;padding:11px;color:var(--gold2);overflow-wrap:anywhere}
 .rim-forward-source{border-left:3px solid var(--gold);padding:5px 8px;margin:0 0 7px;background:rgba(201,164,93,.08);border-radius:5px;font-size:11px;color:var(--muted)}
 .rim-ad-compact{border:1px solid var(--border);border-radius:12px;padding:10px;background:var(--panel2);margin-top:10px;font-size:13px}
 .rim-ad-compact img{max-width:100%;max-height:150px;object-fit:contain;display:block;margin:6px auto;border-radius:8px}
 .rim-ad-compact a{display:inline-block;color:var(--gold2);margin-top:7px}
 @media(prefers-reduced-motion:reduce){.rim-skeleton:after{animation:none}}
 `;document.head.appendChild(style);

 // A. Advertising administration. The old implementation called fullPage(), which is
 // private to another IIFE and therefore throws ReferenceError. Render through DOM here.
 function openPage(title,html){document.getElementById('rimFullPage')?.remove();const root=document.createElement('section');root.id='rimFullPage';root.className='rim-fullpage';root.innerHTML=`<header class="rim-page-head"><button class="icon-btn" onclick="rimClosePage()">‹</button><div class="rim-page-title">${esc(title)}</div><button class="icon-btn rim-floating-close" onclick="rimClosePage()">×</button></header><div class="rim-page-body">${html}</div>`;document.querySelector('.main')?.appendChild(root);}
 if(window.__RIM_ADMIN_COMMANDS_OWNED){/* modular owns admin */}else window.rimAdmin=async function(){
   if(!currentUser)return notify('Сначала войдите в аккаунт.');
   try{await loadImperialRole();}catch(e){console.error('RIM admin role check',e);return notify('Не удалось проверить права администратора.');}
   if(!canManageAds())return notify('Доступ закрыт: требуется роль superadmin.');
   const {data:settings,error:se}=await db.from('rim_platform_settings').select('ads_enabled').eq('id',true).maybeSingle();
   if(se)return notify('Не удалось загрузить глобальные настройки рекламы: '+se.message);
   openPage('Императорская панель',`
    <div class="card"><h3>Глобальное управление рекламой</h3><div class="rim-settings-line"><div><b>Реклама во всём РИМе</b><small>Отключение скрывает все рекламные размещения, не удаляя кампании и статистику.</small></div><input class="rim-switch" id="rimAdsEnabled" type="checkbox" ${settings?.ads_enabled!==false?'checked':''} onchange="rimToggleAds(this.checked)"></div><div id="rimAdsGlobalStatus" class="feature-small">${settings?.ads_enabled===false?'Реклама отключена.':'Реклама включена.'}</div></div>
    <div class="card"><h3>Создать рекламную кампанию</h3><p class="feature-small">Публикация рекламы после последней записи в выбранном канале. Если канал не выбран — общая рекламная кампания для каналов.</p>
     <input id="rimAdSearch" class="field" placeholder="Найти канал по названию или @username" oninput="rimFindAdChannels()"><div id="rimAdChannelResults" class="ils-list"></div>
     <label class="field-label">Заголовок объявления</label><input id="rimAdTitle" class="field" maxlength="120" placeholder="Заголовок рекламы">
     <label class="field-label">Текст объявления</label><textarea id="rimAdBody" class="field" rows="3" maxlength="2000" placeholder="Текст объявления"></textarea>
     <label class="field-label">Изображение (необязательно)</label><input id="rimAdImage" class="field" type="file" accept="image/jpeg,image/png,image/webp,image/gif">
     <label class="field-label">Ссылка перехода</label><input id="rimAdUrl" class="field" type="url" placeholder="https://...">
     <label class="field-label">Сумма договора (₽)</label><input id="rimAdAmount" class="field" type="number" min="0" step="0.01" value="0">
     <label class="field-label">Оплата</label><select id="rimAdPayment" class="field"><option value="unpaid">Не оплачено</option><option value="pending">Ожидается</option><option value="paid">Оплачено</option><option value="refunded">Возврат</option></select>
     <button class="primary-btn" style="width:100%;margin-top:10px" onclick="rimSaveAd()">Сохранить рекламу</button></div>
    <div class="card"><div class="row"><h3 class="grow">Рекламные кампании</h3><button class="action-btn" onclick="rimLoadAdsAdmin()">Обновить</button></div><div id="rimAdsList"><div class="rim-skeleton"></div><div class="rim-skeleton"></div></div></div>
    <div class="card"><div class="row"><h3 class="grow">Статистика</h3><button class="action-btn" onclick="rimLoadStats()">Обновить</button></div><div id="rimStats">Нажмите «Обновить».</div></div>`);
   await window.rimLoadAdsAdmin();
 };
 window.rimToggleAds=async function(enabled){if(!canManageAds())return notify('Недостаточно прав.');const {error}=await db.from('rim_platform_settings').update({ads_enabled:!!enabled,updated_by:currentUser.id,updated_at:new Date().toISOString()}).eq('id',true);if(error){notify('Не удалось изменить режим рекламы: '+error.message);const c=$('rimAdsEnabled');if(c)c.checked=!enabled;return;}if($('rimAdsGlobalStatus'))$('rimAdsGlobalStatus').textContent=enabled?'Реклама включена.':'Реклама отключена.';notify(enabled?'Реклама включена.':'Вся реклама отключена.');};
 window.rimFindAdChannels=async function(){const q=$('rimAdSearch')?.value.trim();const out=$('rimAdChannelResults');if(!out)return;if(!q||q.length<2){out.innerHTML='<div class="feature-small">Введите минимум два символа.</div>';return;}const term=q.replace(/[,%()]/g,' ').trim();const {data,error}=await db.from('channels').select('id,title,username').or(`title.ilike.%${term}%,username.ilike.%${term}%`).order('title').limit(30);if(error){out.textContent='Поиск каналов недоступен: '+error.message;return;}out.innerHTML=(data||[]).map(c=>`<label class="rim-search-result"><input type="radio" name="rimAdChannel" value="${esc(c.id)}"><span><b>${esc(c.title)}</b><small class="feature-small">${c.username?'@'+esc(c.username):''}</small></span></label>`).join('')||'<div class="empty-state">Каналы не найдены.</div>';};
 window.rimSaveAd=async function(){if(!canManageAds())return notify('Требуется роль superadmin.');const title=$('rimAdTitle')?.value.trim(),body=$('rimAdBody')?.value.trim();let url=$('rimAdUrl')?.value.trim()||null;const selected=document.querySelector('input[name="rimAdChannel"]:checked')?.value||null,file=$('rimAdImage')?.files?.[0],amount=Number($('rimAdAmount')?.value||0),payment=$('rimAdPayment')?.value||'unpaid';if(!title||!body)return notify('Заполните заголовок и текст объявления.');if(url){if(/^@[a-z0-9_]{3,24}$/i.test(url))url='rim:'+url;else if(/^tg:@[a-z0-9_]{3,32}$/i.test(url))url=url;else if(/^rim:@[a-z0-9_]{3,24}$/i.test(url))url=url;else if(!/^https?:\/\//i.test(url))return notify('Укажите https://ссылку, @username канала РИМа или tg:@username канала Telegram.');}if(!Number.isFinite(amount)||amount<0)return notify('Некорректная сумма договора.');if(file&&(!['image/jpeg','image/png','image/webp','image/gif'].includes(file.type)||file.size>5*1024*1024))return notify('Изображение должно быть JPG, PNG, WEBP или GIF до 5 МБ.');let media=null;if(file){const path=currentUser.id+'/'+crypto.randomUUID()+'.'+extOf(file.name);const {error}=await db.storage.from('rim-advertising').upload(path,file,{contentType:file.type,upsert:false});if(error)return notify('Не удалось загрузить изображение: '+error.message);media=path;}
   const {data:campaign,error}=await db.from('ad_campaigns').insert({title,body,media_url:media,destination_url:url,placement:'channel_feed',status:'active',created_by:currentUser.id}).select('id').single();if(error){if(media)await db.storage.from('rim-advertising').remove([media]);return notify('Не удалось создать кампанию: '+error.message);}if(selected){const {error:te}=await db.from('ad_campaign_targets').insert({campaign_id:campaign.id,target_type:'channel',channel_id:selected});if(te){await db.from('ad_campaigns').delete().eq('id',campaign.id);if(media)await db.storage.from('rim-advertising').remove([media]);return notify('Не удалось назначить канал: '+te.message);}}
   const {error:fe}=await db.from('ad_campaign_financials').upsert({campaign_id:campaign.id,contract_amount:amount,currency:'RUB',payment_status:payment,updated_at:new Date().toISOString()});if(fe)return notify('Кампания создана, но финансовая запись не сохранена: '+fe.message);notify('Рекламная кампания создана.');await window.rimLoadAdsAdmin();};
 window.rimLoadAdsAdmin=async function(){if(!canManageAds())return;const out=$('rimAdsList');if(!out)return;const {data:ads,error}=await db.from('ad_campaigns').select('id,title,body,media_url,destination_url,placement,status,created_at,starts_at,ends_at').order('created_at',{ascending:false}).limit(100);if(error){out.textContent='Не удалось загрузить кампании: '+error.message;return;}if(!ads?.length){out.innerHTML='<div class="empty-state">Рекламных кампаний пока нет.</div>';return;}const ids=ads.map(a=>a.id);const [tr,fin,ev]=await Promise.all([db.from('ad_campaign_targets').select('campaign_id,channel_id').in('campaign_id',ids),db.from('ad_campaign_financials').select('campaign_id,contract_amount,currency,payment_status').in('campaign_id',ids),db.from('ad_events').select('campaign_id,event_type').in('campaign_id',ids)]);const targets=tr.data||[],finance=Object.fromEntries((fin.data||[]).map(x=>[x.campaign_id,x])),events=ev.data||[];out.innerHTML=ads.map(a=>{const t=targets.filter(x=>x.campaign_id===a.id),f=finance[a.id],im=events.filter(x=>x.campaign_id===a.id&&x.event_type==='impression').length,cl=events.filter(x=>x.campaign_id===a.id&&x.event_type==='click').length;return `<article class="feature-comment"><div class="row"><b class="grow">${esc(a.title)}</b><span class="badge">${esc(a.status)}</span></div><div class="feature-small">${esc(a.body||'')}<br>Размещение: ${a.placement==='channel_feed'?'Лента каналов':esc(a.placement)} · ${t.length?'Выбрано каналов: '+t.length:'Все каналы'}</div><div class="feature-small">Показы: ${im} · Переходы: ${cl} · Договор: ${Number(f?.contract_amount||0).toFixed(2)} ${esc(f?.currency||'RUB')} · Оплата: ${esc(f?.payment_status||'—')}</div><div class="feature-actions"><button class="action-btn" onclick="rimSetAdStatus('${a.id}','${a.status==='active'?'paused':'active'}')">${a.status==='active'?'Приостановить':'Активировать'}</button><button class="action-btn" onclick="rimEditAd('${a.id}')">Изменить</button><button class="action-btn danger-btn" onclick="rimDeleteAd('${a.id}')">Удалить</button></div></article>`;}).join('');};
 window.rimSetAdStatus=async function(id,status){if(!canManageAds())return;const {error}=await db.from('ad_campaigns').update({status,updated_at:new Date().toISOString()}).eq('id',id);if(error)return notify('Не удалось изменить кампанию: '+error.message);await rimLoadAdsAdmin();};
 window.rimEditAd=async function(id){if(!canManageAds())return;const {data:a,error}=await db.from('ad_campaigns').select('id,title,body,destination_url,status').eq('id',id).single();if(error)return notify(error.message);const {data:f}=await db.from('ad_campaign_financials').select('contract_amount,payment_status').eq('campaign_id',id).maybeSingle();const title=prompt('Заголовок:',a.title);if(title===null)return;const body=prompt('Текст объявления:',a.body||'');if(body===null)return;const url=prompt('Ссылка (пусто — без ссылки):',a.destination_url||'');if(url===null)return;const amountRaw=prompt('Сумма договора (₽):',String(f?.contract_amount||0));if(amountRaw===null)return;const amount=Number(amountRaw);if(!Number.isFinite(amount)||amount<0)return notify('Некорректная сумма.');const {error:ue}=await db.from('ad_campaigns').update({title:title.trim(),body:body.trim(),destination_url:url.trim()||null,updated_at:new Date().toISOString()}).eq('id',id);if(ue)return notify('Не удалось изменить кампанию: '+ue.message);const {error:fe}=await db.from('ad_campaign_financials').upsert({campaign_id:id,contract_amount:amount,currency:'RUB',payment_status:f?.payment_status||'unpaid',updated_at:new Date().toISOString()});if(fe)return notify('Кампания изменена, но финансовые данные не сохранены: '+fe.message);await rimLoadAdsAdmin();};
 window.rimDeleteAd=async function(id){if(!canManageAds()||!confirm('Удалить рекламную кампанию?'))return;const {data:a}=await db.from('ad_campaigns').select('media_url').eq('id',id).maybeSingle();const {error}=await db.from('ad_campaigns').delete().eq('id',id);if(error)return notify('Не удалось удалить кампанию: '+error.message);if(a?.media_url)await db.storage.from('rim-advertising').remove([a.media_url]);await rimLoadAdsAdmin();};
 window.rimLoadStats=async function(){if(!canManageAds())return;const out=$('rimStats');if(!out)return;const [profiles,events,fin]=await Promise.all([db.from('profiles').select('id',{count:'exact',head:true}),db.from('ad_events').select('event_type,created_at'),db.from('ad_campaign_financials').select('contract_amount,payment_status')]);if(profiles.error||events.error||fin.error){out.textContent='Не удалось загрузить статистику: '+(profiles.error||events.error||fin.error).message;return;}const since=Date.now()-86400000,ev=events.data||[],paid=(fin.data||[]).filter(x=>x.payment_status==='paid').reduce((n,x)=>n+Number(x.contract_amount||0),0);out.innerHTML=`<div class="rim-page-grid"><div class="card"><b>Аккаунты</b><h2>${profiles.count||0}</h2></div><div class="card"><b>Показы за 24 ч.</b><h2>${ev.filter(x=>x.event_type==='impression'&&new Date(x.created_at).getTime()>=since).length}</h2></div><div class="card"><b>Переходы за 24 ч.</b><h2>${ev.filter(x=>x.event_type==='click'&&new Date(x.created_at).getTime()>=since).length}</h2></div><div class="card"><b>Оплачено по договорам</b><h2>${paid.toFixed(2)} ₽</h2></div></div><div class="feature-small">Сумма учитывает только кампании со статусом «Оплачено».</div>`;};
 window.rimAdClick=async function(id,event,channelId=null){if(event)event.stopPropagation();if(!currentUser)return;const {error}=await db.from('ad_events').insert({campaign_id:id,user_id:currentUser.id,event_type:'click',channel_id:channelId});if(error)console.warn('Ad click event:',error.message);};

 // Ads only after actual channel posts. No posts or master switch off = no ad node.
 window.rimRenderAdBanner=async function(channelId){const page=$('rimFullPage');if(!page)return;page.querySelectorAll('.rim-banner').forEach(n=>n.remove());const posts=[...page.querySelectorAll('.rim-channel-post')];if(!posts.length)return;const {data:setting,error:se}=await db.from('rim_platform_settings').select('ads_enabled').eq('id',true).maybeSingle();if(se||setting?.ads_enabled===false)return;const {data:campaigns,error}=await db.from('ad_campaigns').select('id,title,body,media_url,destination_url,placement,starts_at,ends_at').eq('status','active').eq('placement','channel_feed').order('created_at',{ascending:false}).limit(50);if(error||!campaigns?.length)return;const ids=campaigns.map(x=>x.id);const {data:targets}=await db.from('ad_campaign_targets').select('campaign_id,channel_id,target_type').in('campaign_id',ids);const targeted=new Set((targets||[]).filter(t=>t.target_type==='channel').map(t=>t.campaign_id+':'+t.channel_id));const targetedIds=new Set((targets||[]).filter(t=>t.target_type==='channel').map(t=>t.campaign_id));const now=Date.now();const ad=campaigns.find(c=>(!c.starts_at||new Date(c.starts_at).getTime()<=now)&&(!c.ends_at||new Date(c.ends_at).getTime()>now)&&(!targetedIds.has(c.id)||targeted.has(c.id+':'+channelId)));if(!ad)return;let image='';if(ad.media_url){const {data:u}=await db.storage.from('rim-advertising').createSignedUrl(ad.media_url,1800);image=u?.signedUrl||'';}const host=document.createElement('div');host.className='rim-banner';host.id='rimChannelAdSlot';host.innerHTML=`<div class="rim-ad-compact"><div class="feature-small">Реклама</div>${image?`<img src="${esc(image)}" alt="${esc(ad.title)}" loading="lazy">`:''}<b>${esc(ad.title)}</b><div>${esc(ad.body||'')}</div>${ad.destination_url?`<a href="${esc(ad.destination_url)}" target="_blank" rel="noopener" onclick="rimAdClick('${ad.id}',event,'${channelId}')">Подробнее</a>`:''}</div>`;posts[posts.length-1].insertAdjacentElement('afterend',host);const stamp=ad.id+':'+channelId,nowTick=Date.now();if(window.__rimAdLastImpression?.stamp!==stamp||nowTick-window.__rimAdLastImpression.at>5000){window.__rimAdLastImpression={stamp,at:nowTick};const {error:ie}=await db.from('ad_events').insert({campaign_id:ad.id,user_id:currentUser.id,event_type:'impression',channel_id:channelId});if(ie)console.warn('Ad impression:',ie.message);}};
 const oldOpenChannel=window.openChannel;window.openChannel=async function(id){await oldOpenChannel(id);if(!$('rimFullPage'))return;const row=$('rimFullPage').querySelector('.rim-page-body .row');if(row&&!row.querySelector('#rimChannelUsernameBtn')&&currentChannel&&(currentChannel.owner_id===currentUser.id||admin())){const b=document.createElement('button');b.id='rimChannelUsernameBtn';b.className='action-btn';b.textContent='@';b.title='Изменить username канала';b.onclick=()=>{const v=prompt('Username канала:',currentChannel.username||'');if(v!==null)updateChannelUsername(currentChannel.id,v);};row.appendChild(b);}};
 // The existing publish flow reopens the channel; its openChannel wrapper refreshes the ad slot once.

 // B. Settings order: blocked users before the premium/subscription block; subscription stays last.
 const oldSettings=window.openSettings;window.openSettings=function(){const r=oldSettings.apply(this,arguments);setTimeout(()=>{const modal=document.querySelector('#modalRoot .modal');if(!modal)return;let block=$('rimOpenBlocksBtn');if(!block){block=document.createElement('button');block.id='rimOpenBlocksBtn';block.className='action-btn';block.style.cssText='width:100%;margin-top:10px';block.textContent='Заблокированные пользователи';block.onclick=()=>rimOpenBlocks();}const premium=modal.querySelector('.rim-premium-section');if(premium){modal.insertBefore(block,premium);modal.appendChild(premium);}else modal.appendChild(block);const sections=[...modal.children];const subscription=sections.filter(el=>/подписк|императорская благодать|покупка подписки/i.test(el.textContent||''));subscription.forEach(el=>modal.appendChild(el));},0);return r;};
 const oldOpenBlocks=window.rimOpenBlocks;window.rimOpenBlocks=async function(){const {data,error}=await db.from('user_blocks').select('blocked_id,created_at').eq('blocker_id',currentUser.id).order('created_at',{ascending:false});if(error)return notify('Не удалось загрузить чёрный список: '+error.message);const ids=(data||[]).map(x=>x.blocked_id);const {data:profiles}=ids.length?await db.from('profiles').select('id,username,display_name').in('id',ids):{data:[]};const map=Object.fromEntries((profiles||[]).map(p=>[p.id,p]));showModal(`<h2 class="modal-title">Заблокированные пользователи</h2><button class="primary-btn" style="width:100%" onclick="rimAddBlock()">＋ Заблокировать пользователя</button>${(data||[]).map(x=>`<div class="settings-row"><span>${esc(map[x.blocked_id]?.display_name||map[x.blocked_id]?.username||'Пользователь')} <small>@${esc(map[x.blocked_id]?.username||'')}</small></span><button class="action-btn" onclick="rimRemoveBlock('${x.blocked_id}')">Разблокировать</button></div>`).join('')||'<div class="empty-state">Список пуст.</div>'}<button class="action-btn" style="width:100%" onclick="closeModal()">Закрыть</button>`);};

 // C. File and video attachments. The existing image button and all other controls remain.
 function installAttachmentControl(){const composer=document.querySelector('.composer');if(!composer||$('rimAttachmentInput'))return;const input=document.createElement('input');input.type='file';input.id='rimAttachmentInput';input.hidden=true;input.accept='*/*';input.onchange=async()=>{const f=input.files?.[0];input.value='';if(f)await window.rimSendAttachment(f);};composer.insertAdjacentElement('afterbegin',input);const b=document.createElement('button');b.type='button';b.className='icon-btn';b.title='Отправить файл или видео';b.textContent='📎';b.onclick=()=>input.click();const imageButton=composer.querySelector('button[onclick*="imageInput"]');if(imageButton)imageButton.insertAdjacentElement('afterend',b);else composer.insertBefore(b,composer.firstChild);}
 window.rimSendAttachment=async function(file){if(!currentUser||!activeConversation)return notify('Сначала откройте переписку.');if(file.size>50*1024*1024)return notify('Максимальный размер одного файла — 50 МБ.');if(!file.type)return notify('Не удалось определить тип файла.');const path=currentUser.id+'/'+activeConversation.id+'/'+crypto.randomUUID()+'.'+extOf(file.name);notify('Загружаю вложение…');const {error:up}=await db.storage.from('chat-files').upload(path,file,{contentType:file.type,upsert:false});if(up)return notify('Не удалось загрузить файл: '+up.message);const payload={conversation_id:activeConversation.id,sender_id:currentUser.id,body:'',reply_to_message_id:typeof replyTarget!=='undefined'?(replyTarget?.id||null):null};const {data:message,error:me}=await db.from('chat_messages').insert(payload).select('id').single();if(me){await db.storage.from('chat-files').remove([path]);return notify('Файл загружен, но сообщение не создано: '+me.message);}const {error:ae}=await db.from('chat_message_attachments').insert({message_id:message.id,storage_path:path,file_name:file.name.slice(0,255),mime_type:file.type.slice(0,150),media_kind:mediaKind(file),byte_size:file.size});if(ae){await db.from('chat_messages').delete().eq('id',message.id);await db.storage.from('chat-files').remove([path]);return notify('Не удалось прикрепить файл: '+ae.message);}if(typeof cancelReply==='function')cancelReply();await loadMessages();notify('Вложение отправлено.');};
 const oldRender=window.renderMessages;window.renderMessages=async function(){await oldRender.apply(this,arguments);const cache=window.messagesCache||messagesCache||[];if(!cache.length)return;const ids=cache.map(m=>m.id);const {data:atts,error}=await db.from('chat_message_attachments').select('*').in('message_id',ids);if(error){console.warn('RIM attachments:',error.message);}const rows=atts||[];const paths=[...new Set([...cache.filter(m=>m.image_path).map(m=>m.image_path),...rows.map(a=>a.storage_path)])];let signed={};if(paths.length){const {data:sigs,error:se}=await db.storage.from('chat-files').createSignedUrls(paths,3600);if(!se)for(const x of sigs||[])if(x.path&&x.signedUrl)signed[x.path]=x.signedUrl;}
   for(const m of cache){const el=document.querySelector(`.message[data-id="${CSS.escape(m.id)}"]`);if(!el)continue;const source=m.forwarded_from_user_id;if(source){const {data:p}=await db.from('profiles').select('id,username,display_name').eq('id',source).maybeSingle();const h=document.createElement('div');h.className='rim-forward-source';h.textContent='Переслано от '+(p?.display_name||p?.username||'пользователя');el.insertBefore(h,el.firstChild);}
    const list=rows.filter(a=>a.message_id===m.id);for(const a of list){const url=signed[a.storage_path];if(!url)continue;const box=document.createElement('div');box.className='rim-attachment';if(a.media_kind==='image')box.innerHTML=`<img src="${esc(url)}" loading="lazy" alt="${esc(a.file_name)}">`;else if(a.media_kind==='video')box.innerHTML=`<video controls preload="metadata" playsinline src="${esc(url)}"></video><div class="feature-small" style="padding:5px 8px">${esc(a.file_name)}</div>`;else if(a.media_kind==='audio'||a.media_kind==='voice')box.innerHTML=`<audio controls preload="none" src="${esc(url)}"></audio><div class="feature-small" style="padding:5px 8px">${esc(a.file_name)}</div>`;else box.innerHTML=`<a class="rim-attachment-file" href="${esc(url)}" target="_blank" rel="noopener" download="${esc(a.file_name)}"><span>📄</span><span><b>${esc(a.file_name)}</b><small class="feature-small"> ${(a.byte_size/1024/1024).toFixed(2)} МБ</small></span></a>`;el.querySelector('.message-body')?.insertAdjacentElement('afterend',box)||el.appendChild(box);}
   }
 };

 // D. Forwarding retains source author and copies attachments into the destination conversation.
 window.rimDoForward=async function(id,conversationId){const m=(window.messagesCache||messagesCache||[]).find(x=>x.id===id);if(!m)return notify('Исходное сообщение не найдено.');const payload={conversation_id:conversationId,sender_id:currentUser.id,body:m.body||'',sticker_id:m.sticker_id||null,forwarded_from_user_id:m.forwarded_from_user_id||m.sender_id,forwarded_from_message_id:m.forwarded_from_message_id||m.id};let copied=[];if(m.image_path){const target=currentUser.id+'/'+conversationId+'/'+crypto.randomUUID()+'.'+extOf(m.image_path);const {error}=await db.storage.from('chat-files').copy(m.image_path,target);if(error)return notify('Не удалось скопировать изображение для пересылки: '+error.message);payload.image_path=target;}
   const {data:message,error}=await db.from('chat_messages').insert(payload).select('id').single();if(error)return notify('Не удалось переслать сообщение: '+error.message);const {data:sourceAtt,error:ae}=await db.from('chat_message_attachments').select('*').eq('message_id',m.id);if(ae){await db.from('chat_messages').delete().eq('id',message.id);return notify('Не удалось прочитать вложения исходного сообщения: '+ae.message);}for(const a of sourceAtt||[]){const target=currentUser.id+'/'+conversationId+'/'+crypto.randomUUID()+'.'+extOf(a.file_name);const {error:ce}=await db.storage.from('chat-files').copy(a.storage_path,target);if(ce){for(const p of copied)await db.storage.from('chat-files').remove([p]);await db.from('chat_messages').delete().eq('id',message.id);return notify('Не удалось скопировать вложение: '+ce.message);}copied.push(target);const {error:ins}=await db.from('chat_message_attachments').insert({message_id:message.id,storage_path:target,file_name:a.file_name,mime_type:a.mime_type,media_kind:a.media_kind,byte_size:a.byte_size,duration_seconds:a.duration_seconds,width:a.width,height:a.height});if(ins){await db.from('chat_messages').delete().eq('id',message.id);for(const p of copied)await db.storage.from('chat-files').remove([p]);return notify('Не удалось перенести описание вложения: '+ins.message);}}
   closeModal();notify('Сообщение переслано с указанием автора.');if(activeConversation?.id===conversationId)await loadMessages();};

 // E. Music list: one batch for signed URLs instead of one network round-trip per track.
 window.loadMusic=async function(){const list=$('musicList');if(!list||!currentUser)return;list.innerHTML='<div class="rim-skeleton"></div><div class="rim-skeleton"></div><div class="rim-skeleton"></div>';const {data:tracks,error}=await db.from('music_tracks').select('id,title,artist,file_path,visibility,user_id').order('title').limit(200);if(error){list.innerHTML='<div class="notice">'+esc(error.message)+'</div>';return;}if(!tracks?.length){list.innerHTML='<div class="empty-state">Музыкальная библиотека пока пуста.</div>';return;}const paths=tracks.map(t=>t.file_path);const {data:urls,error:ue}=await db.storage.from('music-library').createSignedUrls(paths,3600);if(ue){list.innerHTML='<div class="notice">Не удалось подготовить аудиофайлы: '+esc(ue.message)+'</div>';return;}const map=Object.fromEntries((urls||[]).filter(x=>x.path&&x.signedUrl).map(x=>[x.path,x.signedUrl]));list.innerHTML='';for(const t of tracks){const url=map[t.file_path];if(!url)continue;const item=document.createElement('div');item.className='card';item.innerHTML=`<strong>${esc(t.title)}</strong><div class="muted" style="font-size:11px;margin:5px 0">${t.visibility==='public'?'Доступен всем':'Личный трек'}${t.artist?' · '+esc(t.artist):''}</div><audio controls preload="none" style="width:100%"></audio>`;item.querySelector('audio').src=url;list.appendChild(item);}if(!list.children.length)list.innerHTML='<div class="empty-state">Нет доступных треков.</div>';};

 // Install controls once the composer exists and after any app navigation rerender.
 const obs=new MutationObserver(()=>{installAttachmentControl();});obs.observe(document.body,{childList:true,subtree:true});installAttachmentControl();
 console.info('[RIM UPDATE-5] patch initialized');
})();

